import{_ as a,o as t,c as n,ag as o}from"./chunks/framework.CAfGEm1x.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md"}'),s={name:"troubleshooting.md"};function i(r,e,l,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="the-command-only-prints-help" tabindex="-1">The command only prints help <a class="header-anchor" href="#the-command-only-prints-help" aria-label="Permalink to &quot;The command only prints help&quot;">​</a></h2><p>Bare <code>kundol</code> shows the welcome screen; bare <code>kundol optimise</code> shows help. Choose a scope such as <code>kundol optimise projects ~/Projects</code>. Use the British spelling <code>optimise</code>.</p><p>For exact options, run <code>kundol optimise projects --help</code> or open the <a href="./reference/cli.html">command reference</a>. There are no public <code>scan</code>, <code>clean</code>, <code>--dry-run</code>, <code>--apply</code>, or <code>--json</code> workflow options.</p><h2 id="the-plan-appears-but-nothing-changes" tabindex="-1">The plan appears, but nothing changes <a class="header-anchor" href="#the-plan-appears-but-nothing-changes" aria-label="Permalink to &quot;The plan appears, but nothing changes&quot;">​</a></h2><ul><li>A blank selection cancels. In a terminal, enter <code>y</code> for safe suggestions or displayed numbers for explicit review.</li><li>Piped and other non-interactive runs cancel unless <code>-f</code> is supplied. Use <code>-f</code> only when you intend to apply safe, force-eligible targets.</li><li>Protected entries are inventory only. Beta status alone does not mean a rule has an executable handler.</li><li>Read each skipped or unavailable reason. A target may have changed since planning or failed an activity, ownership, or identity check.</li></ul><h2 id="a-tool-or-target-is-unavailable" tabindex="-1">A tool or target is unavailable <a class="header-anchor" href="#a-tool-or-target-is-unavailable" aria-label="Permalink to &quot;A tool or target is unavailable&quot;">​</a></h2><ul><li>Run the command from the relevant package workspace when reviewing Bun or Yarn caches.</li><li>Confirm the owner tool is installed and available in the same shell. Yarn beta cache review supports Classic 1.x; modern Yarn is rejected.</li><li>Supply a real workdir containing recognized project markers. Discovery stops at depth 7 and skips symlinks and protected/generated directories.</li><li>Beta Python environment rules run on Linux only; they skip on macOS.</li><li>Use <code>kundol tools list</code> to distinguish unpublished catalogue entries from supported rules.</li></ul><h2 id="generated-file-deletion-fails" tabindex="-1">Generated-file deletion fails <a class="header-anchor" href="#generated-file-deletion-fails" aria-label="Permalink to &quot;Generated-file deletion fails&quot;">​</a></h2><p>Check that <code>/usr/bin/python3</code> is available and supports descriptor-based filesystem operations. Kundol refuses this deletion path when the helper is unavailable. Read the exact target error for permissions or changed-path checks before retrying.</p><h2 id="docker-produces-no-cleanup-targets" tabindex="-1">Docker produces no cleanup targets <a class="header-anchor" href="#docker-produces-no-cleanup-targets" aria-label="Permalink to &quot;Docker produces no cleanup targets&quot;">​</a></h2><p>Supply an explicit context name and ensure its daemon is reachable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> context</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kundol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> optimise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-context</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-beta</span></span></code></pre></div><p>Kundol pins that context and daemon identity. There is currently no published Docker resource cleanup rule; <code>--allow-beta</code> adds protected network and volume inventories only. Docker has no force option.</p><h2 id="a-size-is-unknown" tabindex="-1">A size is unknown <a class="header-anchor" href="#a-size-is-unknown" aria-label="Permalink to &quot;A size is unknown&quot;">​</a></h2><p>Directory measurement stops after its scan budget. An incomplete measurement appears as unknown, and owner-tool actions may also have unknown savings. Known reclaimed bytes are not a complete measurement of every action&#39;s disk effect.</p><h2 id="interpret-exit-codes-and-audit-warnings" tabindex="-1">Interpret exit codes and audit warnings <a class="header-anchor" href="#interpret-exit-codes-and-audit-warnings" aria-label="Permalink to &quot;Interpret exit codes and audit warnings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Result</th><th>Exit code</th></tr></thead><tbody><tr><td>Successful run or cancelled selection</td><td><code>0</code></td></tr><tr><td>One or more apply failures</td><td><code>70</code></td></tr></tbody></table><p>Argument and parsing errors can also return a nonzero code. Read the terminal output alongside the code; cancellation is not evidence that cleanup occurred.</p><p>Audit records live under <code>~/.kundol/</code>. If an audit warning appears after an action, inspect its reported outcome before rerunning: the action may have succeeded even though its audit write failed.</p><h2 id="report-a-problem-or-request-a-rule" tabindex="-1">Report a problem or request a rule <a class="header-anchor" href="#report-a-problem-or-request-a-rule" aria-label="Permalink to &quot;Report a problem or request a rule&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kundol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> issue</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kundol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> request</span></span></code></pre></div><p>These open GitHub in a browser and print a URL you can open manually. Review and submit the issue yourself. Include your version, operating system, command, and relevant output; remove private paths or other sensitive details before sharing.</p>`,23)])])}const k=a(s,[["render",i]]);export{u as __pageData,k as default};
